<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { formatTime } from './api'
import { qualityLabel } from './quality'
import Icon from './Icon.vue'
import ListeningScene from './ListeningScene.vue'
import './player-stage.css'
const props=defineProps({track:Object,audio:Object,playing:Boolean,preparing:Boolean,buffering:Boolean,elapsed:Number,duration:Number,volume:Number,lyricLines:Array,activeLine:Number,quality:String,actualQuality:String,qualityOptions:Array,liked:Boolean,shuffle:Boolean,repeat:String,playlists:Array,error:String})
const emit=defineEmits(['close','toggle','seek','previous','next','favorite','queue','quality','volume','shuffle','repeat','add-playlist','retry'])
const root=ref(null),scene=ref(null),lyricElements=ref([]),mobileView=ref('cover'),mode=ref(localStorage.getItem('sq-scene-mode')||'aurora'),signal=ref('ambient'),coverFailed=ref(0),lyricViewport=ref(null)
const highCover=computed(()=>props.track.coverUrl?.replace(/(y\.gtimg\.cn\/music\/photo_new\/T002)R\d+x\d+(M000)/,'$1R800x800$2'))
const cover=computed(()=>coverFailed.value===0?highCover.value:coverFailed.value===1?props.track.coverUrl:'')
const progress=computed(()=>props.duration?Math.min(100,props.elapsed/props.duration*100):0)
const modeLabel=computed(()=>mode.value==='still'?'静谧':mode.value==='spectrum'?'频谱':'流光')
function setMode(value){mode.value=value;localStorage.setItem('sq-scene-mode',value);scene.value?.activate()}
function toggle(){scene.value?.activate();emit('toggle')}
async function centerLyric(){await nextTick();const line=lyricElements.value[props.activeLine],viewport=lyricViewport.value;if(line&&viewport)viewport.scrollTo({top:line.offsetTop-viewport.offsetTop-viewport.clientHeight*.45+line.clientHeight*.5,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
watch(()=>props.activeLine,centerLyric)
watch(mobileView,async()=>{await centerLyric();scene.value?.layout()})
watch(()=>props.track.id,()=>{coverFailed.value=0;lyricElements.value=[]})
let resizeObserver
onMounted(()=>{centerLyric();resizeObserver=new ResizeObserver(centerLyric);resizeObserver.observe(root.value)})
onUnmounted(()=>resizeObserver?.disconnect())
defineExpose({querySelector:selector=>root.value?.querySelector(selector)})
</script>
<template>
  <section ref="root" class="immersive-player player-stage" :class="{'stage-playing':playing,'stage-show-lyrics':mobileView==='lyrics','stage-has-lyrics':lyricLines.length}" role="dialog" aria-modal="true" aria-label="正在播放" @keydown.esc="emit('close')">
    <ListeningScene ref="scene" :audio="audio" :cover="track.coverUrl" :playing="playing" :mode="mode" @signal="signal=$event" />
    <header class="stage-header"><button class="stage-icon" aria-label="收起播放器" @click="emit('close')"><Icon name="down" :size="25" /></button><div class="stage-source"><span class="stage-wordmark">SQ MUSIC</span><span>{{track.local?'我的音乐库':'在线音乐'}}<i></i>{{actualQuality || '正在准备'}}</span></div><button class="stage-icon" aria-label="显示播放队列" @click="emit('queue')"><Icon name="queue" :size="24" /></button></header>
    <div class="stage-view-switch" role="group" aria-label="播放视图"><button :aria-pressed="mobileView==='cover'" @click="mobileView='cover'">封面</button><button :aria-pressed="mobileView==='lyrics'" @click="mobileView='lyrics'">歌词</button></div>
    <main class="stage-body">
      <div class="stage-record"><div class="cover-stage"><div class="cover-light" :style="cover?{backgroundImage:`url(${JSON.stringify(cover)})`}:{}"></div><figure class="stage-cover" :key="track.id"><img v-if="cover" :src="cover" :alt="(track.album || track.title)+' 专辑封面'" @error="coverFailed++" /><div v-else class="stage-cover-missing"><Icon name="music" :size="86" /><span>{{track.title}}</span></div><div class="cover-edge"></div></figure><div class="cover-shadow"></div></div><div class="stage-album-caption"><span>{{track.album || '单曲'}}</span><span>{{track.local?'NAS COLLECTION':'ORIGINAL ALBUM'}}</span></div><div class="stage-song"><div><h1>{{track.title}}</h1><p>{{track.artist}}</p></div><button class="stage-icon stage-like" :class="{liked}" :aria-pressed="liked" aria-label="喜欢当前歌曲" @click="emit('favorite')"><Icon name="heart" :size="27" /></button></div></div>
      <section class="stage-lyrics" aria-label="同步歌词"><div class="lyric-caption"><span>歌词</span><span v-if="lyricLines.length">随音乐，慢慢展开</span></div><div v-if="lyricLines.length" ref="lyricViewport" class="stage-lyric-scroll"><button v-for="(line,index) in lyricLines" :key="index" :ref="el=>lyricElements[index]=el" :class="{'is-current':activeLine===index,'is-past':index<activeLine}" @click="emit('seek',line.time)">{{line.text}}</button></div><div v-else class="stage-no-lyrics"><span class="no-lyrics-mark">♪</span><h2>{{track.title}}</h2><p>{{track.artist}}</p><small>这首歌暂时没有同步歌词</small></div></section>
    </main>
    <footer class="stage-dock"><div v-if="error" class="stage-error" role="alert"><span>{{error}}</span><button @click="emit('retry')">重试</button></div><div class="stage-timeline"><time>{{formatTime(elapsed)}}</time><input type="range" aria-label="播放进度" min="0" :max="duration||1" step=".1" :value="elapsed" :style="{'--played':progress+'%'}" @input="emit('seek',Number($event.target.value))" /><time>{{formatTime(duration)}}</time></div><div class="stage-controls"><div class="stage-tools"><label class="stage-quality"><span class="quality-symbol">{{/flac/i.test(actualQuality)?'SQ':'HQ'}}</span><span>{{actualQuality || '最高可用'}}</span><Icon name="down" :size="13" /><select :value="quality" aria-label="在线播放音质" :disabled="preparing||track.local" @change="emit('quality',$event.target.value)"><option value="auto">最高可用（默认）</option><option v-for="value in qualityOptions" :key="value" :value="value">{{qualityLabel(value)}}</option></select></label><label v-if="playlists.length" class="stage-add"><Icon name="plus" :size="18" /><span>歌单</span><select value="" aria-label="当前歌曲加入歌单" @change="emit('add-playlist',$event)"><option value="" disabled>加入歌单</option><option v-for="list in playlists" :key="list.id" :value="list.id">{{list.name}}</option></select></label></div><div class="stage-transport"><button class="stage-icon side-control" :class="{toggled:shuffle}" :aria-pressed="shuffle" aria-label="随机播放" @click="emit('shuffle')"><Icon name="shuffle" :size="21" /></button><button class="stage-icon" aria-label="上一首" @click="emit('previous')"><Icon name="prev" :size="25" /></button><button class="stage-play" :disabled="preparing" :aria-label="playing?'暂停':'播放'" @click="toggle"><span v-if="preparing||buffering" class="loading-ring"></span><Icon v-else :name="playing?'pause':'play'" :size="27" /></button><button class="stage-icon" aria-label="下一首" @click="emit('next')"><Icon name="next" :size="25" /></button><button class="stage-icon side-control" :class="{toggled:repeat!=='off'}" :aria-label="'循环模式：'+({off:'关闭',all:'列表循环',one:'单曲循环'})[repeat]" @click="emit('repeat')"><Icon name="repeat" :size="21" /><small v-if="repeat==='one'">1</small></button></div><div class="stage-right-tools"><div class="scene-modes" role="group" aria-label="视觉效果"><button v-for="option in [{id:'aurora',label:'流光'},{id:'spectrum',label:'频谱'},{id:'still',label:'静谧'}]" :key="option.id" :aria-pressed="mode===option.id" @click="setMode(option.id)">{{option.label}}</button></div><div class="stage-volume"><Icon name="volume" :size="19" /><input type="range" min="0" max="1" step=".01" :value="volume" aria-label="音量" @input="emit('volume',Number($event.target.value))" /></div></div></div><div class="stage-footnote"><span class="signal-dot" :class="{live:signal==='live'&&playing}"></span><span>{{mode==='still'?'静谧模式':signal==='live'&&playing?'随音乐律动':modeLabel+'氛围'}}</span><span class="stage-shortcut">空格键播放 / 暂停</span></div></footer>
  </section>
</template>
